// auipc reads the pc: two adjacent ones differ by exactly 4, and the run
// around them must keep that.
static uint64_t auipc_case(void) {
    uint64_t d;
    __asm__ volatile(".option push\n .option norvc\n auipc t0, 0\n auipc t1, 0\n"
                     " sub t2, t1, t0\n addi t2, t2, 1\n slli %0, t2, 2\n .option pop"
                     : "=r"(d) :: "t0", "t1", "t2");
    return d;
}

#define FUSE_NODE "/proc/ish/riscv64_jit_fuse"
// The node's "rcache on|off" line: 1, 0, or -1 when unreadable.
static int rcache_state(void) {
    FILE *f = fopen(FUSE_NODE, "r");
    char line[64];
    int on = -1;
    while (f != NULL && fgets(line, sizeof(line), f) != NULL)
        if (strncmp(line, "rcache ", 7) == 0)
            on = strncmp(line + 7, "on", 2) == 0;
    if (f != NULL)
        fclose(f);
    return on;
}
static void rcache_set(int on) {
    FILE *f = fopen(FUSE_NODE, "w");
    if (f != NULL) {
        fprintf(f, "rcache=%d\n", on);
        fclose(f);
    }
}

int main(void) {
    int fails = 0, n = sizeof(cases) / sizeof(cases[0]);
    int was = rcache_state(), want = getenv("ISH_RCACHE_TEST_OFF") == NULL;
    if (was >= 0 && was != want)
        rcache_set(want);
    if (was >= 0 && rcache_state() != want)
        printf("note: could not set rcache=%d (not root?)\n", want);
    for (int i = 0; i < n; i++) {
        for (int rep = 0; rep < 2; rep++) {
            uint64_t r[6];
            for (int j = 0; j < 6; j++)
                r[j] = cases[i].in[j];
            cases[i].fn(r);
            for (int j = 0; j < 6; j++)
                if (r[j] != cases[i].want[j]) {
                    printf("FAIL: case %d rep %d reg %d: %#llx want %#llx\n", i, rep, j,
                           (unsigned long long) r[j], (unsigned long long) cases[i].want[j]);
                    fails++;
                }
        }
    }
    uint64_t a = auipc_case();
    if (a != 20) {
        printf("FAIL: auipc run gave %llu, want 20\n", (unsigned long long) a);
        fails++;
    }
    if (was >= 0 && was != want)
        rcache_set(was);
    printf("rcache_run: %s (%d cases, rcache %s)\n", fails ? "FAIL" : "PASS", n + 1,
           want ? "on" : "off");
    return fails != 0;
}

#else
int main(void) {
    printf("rcache_run: SKIP (riscv64 only)\n");
    return 0;
}
#endif
